    public static IHtmlContent Svg(string? name, string cssClass = "size-6")
    {
        if (name is null || !Paths.TryGetValue(name, out var paths))
        {
            paths = Paths["fabrication"];
        }

        var d = string.Concat(paths.Select(p => $"<path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"{p}\" />"));
        return new HtmlString(
            $"<svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"1.5\" stroke=\"currentColor\" class=\"{WebUtility.HtmlEncode(cssClass)}\" aria-hidden=\"true\">{d}</svg>");
    }
